package ama.transcript;
import ama.contract.MinutesContracts.*;
import java.util.*;
import static ama.contract.MinutesContracts.*;
import static ama.contract.MinutesContracts.FailureCode.*;
/** Full fresh copy, prepared outside roots; both automatic first-save and explicit adoption use this plan. */
final class MinutesSavedGraphPlan {
 private final String body,set;private final List<FullRow> templates;private final TranscriptAcquisitionBudget.Ledger budget;
 private MinutesSavedGraphPlan(String body,String set,List<FullRow> templates,TranscriptAcquisitionBudget.Ledger budget){this.body=body;this.set=set;this.templates=List.copyOf(templates);this.budget=budget;}
 String body(){return body;}String set(){return set;}
 static MinutesSavedGraphPlan candidate(MinutesCandidateGraphPlan candidate,MinutesGraphCapture.Graph graph,TranscriptAcquisitionBudget.Ledger budget){var rows=new ArrayList<>(candidate.rows(1,1));rows.addAll(candidate.reusedLocators());return copy(candidate.bodyId(),candidate.setId(),rows,(String)graph.discovery().root().get("minutes_revision_id"),candidate.owner(),budget);}
 static MinutesSavedGraphPlan copy(String sourceBody,String sourceSet,List<FullRow> complete,String parent,String actor,TranscriptAcquisitionBudget.Ledger budget){
  JdbcMinutesFactsReader.independent();var owners=Set.of(Table.MINUTES_REVISION,Table.ELEMENT_SET,Table.MINUTES_ELEMENT,Table.SENSITIVE_DETECTION,Table.BACKGROUND_NOTE,Table.SOURCE_LOCATOR,Table.EVIDENCE_LINK);var maps=new EnumMap<Table,Map<String,String>>(Table.class);for(Table table:owners)maps.put(table,new HashMap<>());
  var body=complete.stream().filter(r->r.table()==Table.MINUTES_REVISION&&sourceBody.equals(r.string("id"))).toList();var set=complete.stream().filter(r->r.table()==Table.ELEMENT_SET&&sourceSet.equals(r.string("id"))).toList();require(body.size()==1&&set.size()==1&&body.getFirst().nullableString("generation_input_id")!=null,PROVENANCE_UNAVAILABLE);
  String meeting=body.getFirst().string("meeting_id");require(meeting.equals(set.getFirst().string("meeting_id")),PROVENANCE_UNAVAILABLE);
  var selected=new ArrayList<FullRow>();selected.add(body.getFirst());selected.add(set.getFirst());
  var elementIds=new HashSet<String>();var detectionIds=new HashSet<String>();var noteIds=new HashSet<String>();var locatorIds=new HashSet<String>();
  for(var row:complete)if(Set.of(Table.MINUTES_ELEMENT,Table.SENSITIVE_DETECTION,Table.BACKGROUND_NOTE).contains(row.table())&&sourceSet.equals(row.string("set_id"))){selected.add(row);(row.table()==Table.MINUTES_ELEMENT?elementIds:row.table()==Table.SENSITIVE_DETECTION?detectionIds:noteIds).add(row.string("id"));}
  for(var row:complete){boolean include=switch(row.table()){case ACTION_ITEM,ACTION_SUGGESTION->elementIds.contains(row.string("element_id"));case SENSITIVE_DETECTION_SOURCE->detectionIds.contains(row.string("detection_id"));case BACKGROUND_NOTE_SOURCE->noteIds.contains(row.string("note_id"));case EVIDENCE_LINK->sourceBody.equals(row.nullableString("minutes_revision_id"))||elementIds.contains(row.nullableString("element_id"));default->false;};if(include){selected.add(row);if(Set.of(Table.SENSITIVE_DETECTION_SOURCE,Table.BACKGROUND_NOTE_SOURCE,Table.EVIDENCE_LINK).contains(row.table()))locatorIds.add(row.string("locator_id"));}}
  for(String id:locatorIds){var found=complete.stream().filter(r->r.table()==Table.SOURCE_LOCATOR&&id.equals(r.string("id"))).distinct().toList();require(found.size()==1&&meeting.equals(found.getFirst().string("meeting_id"))&&"TRANSCRIPT".equals(found.getFirst().string("kind")),PROVENANCE_UNAVAILABLE);selected.add(found.getFirst());}
  for(var row:selected)if(owners.contains(row.table()))require(maps.get(row.table()).put(row.string("id"),UUID.randomUUID().toString())==null,PROVENANCE_UNAVAILABLE);
  String now=java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSSSSS'Z'").format(java.time.LocalDateTime.now(java.time.ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS));var copied=new ArrayList<FullRow>();
  for(var row:selected){budget.row(row.cells().size());var cells=new ArrayList<Cell>();for(int i=0;i<row.cells().size();i++){var column=row.table().columns().get(i);String name=column.name();var value=row.cells().get(i);Table target=switch(name){case "id"->owners.contains(row.table())?row.table():null;case "set_id"->Table.ELEMENT_SET;case "element_id"->Table.MINUTES_ELEMENT;case "minutes_revision_id"->Table.MINUTES_REVISION;case "locator_id"->Table.SOURCE_LOCATOR;case "detection_id"->Table.SENSITIVE_DETECTION;case "note_id"->Table.BACKGROUND_NOTE;default->null;};if(target!=null&&value instanceof TextCell text){String fresh=maps.get(target).get(text.value());require(fresh!=null,PROVENANCE_UNAVAILABLE);value=cell(fresh);}if(row.table()==Table.MINUTES_REVISION&&name.equals("parent_id"))value=parent==null?new NullCell():cell(parent);if(row.table()==Table.MINUTES_REVISION&&name.equals("created_by"))value=cell(actor);if(name.equals("created_at")&&(row.table()==Table.MINUTES_REVISION||row.table()==Table.ELEMENT_SET))value=cell(now);if(value instanceof TextCell text)budget.text(ama.canonical.CanonicalValueCodec.utf8Length(text.value(),()->false),text.value().codePointCount(0,text.value().length()),text.value().length(),8,true);cells.add(value);}copied.add(new FullRow(row.table(),cells));}
  var rank=new HashMap<String,Integer>();for(int i=0;i<MinutesGraphCapture.DOMAIN_RANK.size();i++)rank.put(MinutesGraphCapture.DOMAIN_RANK.get(i),i);copied.sort(Comparator.comparingInt(r->rank.get(r.table().sqlName())));
  return new MinutesSavedGraphPlan(maps.get(Table.MINUTES_REVISION).get(sourceBody),maps.get(Table.ELEMENT_SET).get(sourceSet),copied,budget);
 }
 List<FullRow> rows(long bodyRevision,long setRevision){require(bodyRevision>0&&bodyRevision<Long.MAX_VALUE&&setRevision>0&&setRevision<Long.MAX_VALUE,BUDGET_EXCEEDED);budget.check();return templates.stream().map(row->{if(row.table()!=Table.MINUTES_REVISION&&row.table()!=Table.ELEMENT_SET)return row;var cells=new ArrayList<>(row.cells());cells.set(row.table().index("revision"),cell(row.table()==Table.MINUTES_REVISION?bodyRevision:setRevision));return new FullRow(row.table(),cells);}).toList();}
}
